import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('las-facetas-del-yo-soy-iv', 'B',
 [dict(t=1860, e=1906, titulo='Dios se llevará a los vivientes', txt='Dios se va a llevar a los vivientes. Ya es diferente. Ya es un grupo selecto, ya no es cualquiera, porque a los vivos se llevaría a todos. No es así. Entonces dice en Apocalipsis 1:18: «Yo soy el que vive». […] Y si yo vivo, te doy vida a ti y te vuelvo viviente. Por eso nosotros tenemos que regresar a como estaban en el huerto. En el huerto, ¿qué había? Vivientes.'),
  dict(t=2634, e=2672, titulo='Eternos con el Señor', txt='¿Cuál es el que sigue? Alfa y Omega. Esto es hermoso, porque aquí entramos nosotros, el principio y el fin. Si Jesucristo no tiene ni principio ni fin, nosotros vamos a llegar a ser también así, hermano: eternos. ¿Cuántos se imaginan en el cielo siendo eternos? […] Qué lindo que estemos con el Señor. Aquí practicamos para la eternidad.'),
  dict(t=3790, e=3845, titulo='Usted vino a prepararse', txt='Yo soy el alfa, el omega, yo soy el viviente. […] Yo soy el alfa y el omega, el principio y el fin. Hermano, por favor, entienda que usted no es un simple mortal, que no vino a sufrir y a sufrir a esta tierra. Usted lo que vino es a prepararse para la venida del Señor. Tarde o temprano él volverá y va a regresar por usted y por mí.')],
 [dict(t=1512, txt='Cambiemos, transformémonos a través de la palabra.'),
  dict(t=2485, txt='Te está dando gozo, te está dando unción, y la unción rompe el yugo de esclavitud.'),
  dict(t=3707, txt='No den por tardanza mi venida. Yo vengo pronto.')],
 ['Si Jesús es «el que vive» y quiere hacerte viviente, ¿en qué parte de tu vida sientes que apenas estás existiendo?',
  '¿Qué herida o área de tu vida necesita que dejes que el Señor le eche «vino y aceite» esta semana?',
  'Si no viniste a esta tierra solo a sufrir sino a prepararte para su venida, ¿qué cambiarías hoy en tu forma de vivir?'],
 inicio=979)
